//! Actual B1C080 notification, B1BE30 append and B1BF30 all-match removal.
use std::collections::{BTreeMap,BTreeSet};
use crate::{audio_bus_bank::Error,audio_plugin_factory::Memory};
fn word(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn set(b:&mut[u8],o:usize,v:u32){b[o..o+4].copy_from_slice(&v.to_le_bytes());}
/// Physical regions retain pooled padding and retired-node snapshots. Tombstones
/// prevent retired external slots from being used as live protocol nodes.
pub struct Runtime{pub header:[u8;28],pub regions:BTreeMap<u32,Memory>,pub freed_nodes:BTreeSet<u32>,pub pool:u32}
pub trait Services{
 fn allocate_notification(&mut self,pool:u32,bytes:u32)->Result<Option<Memory>,Error>;
 fn free_notification(&mut self,pool:u32,node:&Memory)->Result<(),Error>;
 fn voice_action(&mut self,voice:&mut Memory,argument:u32,queue:&mut Runtime)->Result<(),Error>;
}
impl Runtime{
 pub(crate) fn read(&self,reference:u32,size:usize)->Result<&[u8],Error>{if self.freed_nodes.iter().any(|r|reference>=*r&&reference.wrapping_sub(*r)<20){return Err(Error::UnresolvedReference);}crate::audio_path_memory::read(&self.regions,reference,size)}
 fn write(&mut self,reference:u32,value:&[u8])->Result<(),Error>{self.read(reference,value.len())?;let base=*self.regions.range(..=reference).next_back().ok_or(Error::UnresolvedReference)?.0;let offset=reference.wrapping_sub(base)as usize;self.regions.get_mut(&base).unwrap().raw[offset..offset+value.len()].copy_from_slice(value);Ok(())}
 pub(crate) fn store(&mut self,reference:u32,value:u32)->Result<(),Error>{self.write(reference,&value.to_le_bytes())}
 pub(crate) fn append(&mut self,services:&mut impl Services)->Result<u32,Error>{
 if word(&self.header,8)==0{if word(&self.header,20)>=word(&self.header,16){return Ok(0);}let Some(memory)=services.allocate_notification(self.pool,20)?else{return Ok(0);};if memory.reference==0||memory.raw.len()!=20{return Err(Error::InvalidAllocation);}let reference=memory.reference;
 if self.freed_nodes.contains(&reference){crate::audio_path_memory::read(&self.regions,reference,20)?;self.freed_nodes.remove(&reference);self.write(reference,&memory.raw)?;}else{if self.regions.iter().any(|(r,m)|(reference as u64)<*r as u64+m.raw.len()as u64&&(*r as u64)<reference as u64+20){return Err(Error::InvalidAllocation);}self.regions.insert(reference,memory);}
 self.store(reference,word(&self.header,8))?;set(&mut self.header,8,reference);}
 let tail=word(&self.header,4);let reference=word(&self.header,8);if tail==0{set(&mut self.header,0,reference);}else{self.store(tail,reference)?;}set(&mut self.header,4,reference);let next=word(self.read(reference,4)?,0);set(&mut self.header,8,next);self.store(reference,0)?;let count=word(&self.header,20).wrapping_add(1);set(&mut self.header,20,count);Ok(reference.wrapping_add(4))
 }
 pub fn remove(&mut self,voice:u32,services:&mut impl Services)->Result<(),Error>{let mut current=word(&self.header,0);let mut previous=0;let mut seen=BTreeSet::new();while current!=0{if !seen.insert(current){return Err(Error::CyclicList);}let node=self.read(current,20)?.to_vec();let next=word(&node,0);if word(&node,4)==voice{if current==word(&self.header,0){set(&mut self.header,0,next);}else{self.store(previous,next)?;}if current==word(&self.header,4){set(&mut self.header,4,previous);}let base=word(&self.header,24);let end=base.wrapping_add(word(&self.header,12).wrapping_mul(20));if current>=base&&current<end{self.store(current,word(&self.header,8))?;let count=word(&self.header,20).wrapping_sub(1);set(&mut self.header,20,count);set(&mut self.header,8,current);}else{services.free_notification(self.pool,&Memory{reference:current,raw:node})?;self.freed_nodes.insert(current);let count=word(&self.header,20).wrapping_sub(1);set(&mut self.header,20,count);}current=next;}else{previous=current;current=next;}}Ok(())}
 pub fn notify(&mut self,voice:&mut Memory,frame:u32,services:&mut impl Services)->Result<u32,Error>{if voice.reference==0||voice.raw.len()<112{return Err(Error::InvalidAllocation);}let mut current=word(&self.header,0);let mut seen=BTreeSet::new();while current!=0{if !seen.insert(current){return Err(Error::CyclicList);}let node=self.read(current,12)?;if word(node,4)==voice.reference{let phase=word(node,8);if (phase==0||phase==1)&&word(&voice.raw,108)==0{self.remove(voice.reference,services)?;services.voice_action(voice,1,self)?;return Ok(1);}break;}current=word(node,0);}
 let payload=self.append(services)?;if payload==0{return Ok(2);}self.store(payload,voice.reference)?;self.store(payload.wrapping_add(4),2)?;self.store(payload.wrapping_add(8),frame)?;self.write(payload.wrapping_add(12),&[0])?;Ok(1)
 }
}
#[cfg(test)]mod tests{
 use super::*;use serde_json::{Value,json};
 fn bytes(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
 fn hex(b:&[u8])->String{b.iter().map(|v|format!("{v:02x}")).collect()}
 struct Backend{pattern:u8,failure:bool,calls:Vec<Value>,freed:Vec<u32>}
 impl Services for Backend{
 fn allocate_notification(&mut self,pool:u32,bytes:u32)->Result<Option<Memory>,Error>{let reference=if self.failure{0}else{0x4000a000};self.calls.push(json!({"kind":"allocate","pool":pool,"bytes":bytes,"reference":reference}));Ok(if reference==0{None}else{Some(Memory{reference,raw:vec![self.pattern;bytes as usize]})})}
 fn free_notification(&mut self,pool:u32,node:&Memory)->Result<(),Error>{assert!(!self.freed.contains(&node.reference));self.freed.push(node.reference);self.calls.push(json!({"kind":"free","pool":pool,"reference":node.reference}));Ok(())}
 fn voice_action(&mut self,voice:&mut Memory,argument:u32,queue:&mut Runtime)->Result<(),Error>{self.calls.push(json!({"kind":"voice_action","voice":voice.reference,"argument":argument,"queue_at_call":hex(&queue.header),"voice_at_call":hex(&voice.raw)}));Ok(())}
 }
 #[test]fn audio_path_voice_notification_matches3072_native_scan_duplicate_remove_pool_recycle_external_free_append_oom_frame_and_padding_cases(){let p:Value=serde_json::from_str(&crate::audio_test_fixture("data/4.20/audio_path_voice_notification_preparation.json")).unwrap();assert_eq!(p["passed"],true);assert_eq!(p["case_count"],3072);for(i,row)in p["cases"].as_array().unwrap().iter().enumerate(){let b=&row["before"];let mut voice=Memory{reference:0x40004000,raw:bytes(b["voice"].as_str().unwrap())};let mut q=Runtime{header:bytes(b["queue"].as_str().unwrap()).try_into().unwrap(),regions:BTreeMap::from([(0x40008000,Memory{reference:0x40008000,raw:bytes(b["storage"].as_str().unwrap())}),(0x40009000,Memory{reference:0x40009000,raw:bytes(b["free_slot"].as_str().unwrap())})]),freed_nodes:BTreeSet::new(),pool:17};let mut backend=Backend{pattern:row["pattern"].as_u64().unwrap()as u8,failure:row["failure"]==true,calls:vec![],freed:vec![]};assert_eq!(q.notify(&mut voice,0x12345678,&mut backend).unwrap(),row["result"].as_u64().unwrap()as u32,"notification status {i}");assert_eq!(json!(backend.calls),row["calls"],"physical calls and action state {i}");assert_eq!(json!(backend.freed),row["freed"],"external free order {i}");let allocated=q.regions.get(&0x4000a000).map(|m|hex(&m.raw)).unwrap_or_else(||b["allocated"].as_str().unwrap().to_string());assert_eq!(json!({"voice":hex(&voice.raw),"queue":hex(&q.header),"storage":hex(&q.regions[&0x40008000].raw),"free_slot":hex(&q.regions[&0x40009000].raw),"allocated":allocated}),row["after"],"complete queue/voice/physical region bytes {i}");}}
 #[test]fn audio_path_voice_notification_cyclic_live_queue_returns_error_before_allocating(){let mut raw=vec![0;20];set(&mut raw,0,100);set(&mut raw,4,999);let mut h=[0;28];set(&mut h,0,100);let mut q=Runtime{header:h,regions:BTreeMap::from([(100,Memory{reference:100,raw})]),freed_nodes:BTreeSet::new(),pool:17};let mut voice=Memory{reference:1,raw:vec![0;424]};let mut backend=Backend{pattern:0,failure:false,calls:vec![],freed:vec![]};assert_eq!(q.notify(&mut voice,0,&mut backend),Err(Error::CyclicList));assert!(backend.calls.is_empty());}
 struct Reuse{inner:Backend,last:bool}
 impl Services for Reuse{fn allocate_notification(&mut self,pool:u32,bytes:u32)->Result<Option<Memory>,Error>{let reference=if self.inner.failure{0}else if self.last{*self.inner.freed.last().unwrap()}else{self.inner.freed[0]};self.inner.calls.push(json!({"kind":"allocate","pool":pool,"bytes":bytes,"reference":reference}));Ok(if reference==0{None}else{Some(Memory{reference,raw:vec![self.inner.pattern;bytes as usize]})})}fn free_notification(&mut self,pool:u32,node:&Memory)->Result<(),Error>{self.inner.free_notification(pool,node)}fn voice_action(&mut self,v:&mut Memory,a:u32,q:&mut Runtime)->Result<(),Error>{self.inner.voice_action(v,a,q)}}
 #[test]fn audio_path_voice_notification_matches48_native_consecutive_freed_first_last_slot_reuse_oom_and_retained_live_region_cases(){let p:Value=serde_json::from_str(include_str!("../../../data/4.20/audio_path_voice_notification_reuse_preparation.json")).unwrap();assert_eq!(p["passed"],true);assert_eq!(p["case_count"],48);for(i,row)in p["cases"].as_array().unwrap().iter().enumerate(){let b=&row["before"];let mut voice=Memory{reference:0x40004000,raw:bytes(b["voice"].as_str().unwrap())};let mut q=Runtime{header:bytes(b["queue"].as_str().unwrap()).try_into().unwrap(),regions:BTreeMap::from([(0x40008000,Memory{reference:0x40008000,raw:bytes(b["storage"].as_str().unwrap())}),(0x40009000,Memory{reference:0x40009000,raw:bytes(b["free_slot"].as_str().unwrap())})]),freed_nodes:BTreeSet::new(),pool:17};let mut backend=Reuse{inner:Backend{pattern:row["pattern"].as_u64().unwrap()as u8,failure:row["failure"]==true,calls:vec![],freed:vec![]},last:row["reuse"]=="last"};let snapshot=|q:&Runtime,v:&Memory|json!({"voice":hex(&v.raw),"queue":hex(&q.header),"storage":hex(&q.regions[&0x40008000].raw),"free_slot":hex(&q.regions[&0x40009000].raw),"allocated":b["allocated"]});assert_eq!(q.notify(&mut voice,0x12345678,&mut backend).unwrap(),row["first_result"].as_u64().unwrap()as u32,"first notification {i}");assert_eq!(snapshot(&q,&voice),row["after_first"],"all physical bytes after free {i}");assert_eq!(json!(backend.inner.calls),row["first_calls"],"first callbacks {i}");assert_eq!(q.notify(&mut voice,0x12345678,&mut backend).unwrap(),row["result"].as_u64().unwrap()as u32,"second notification {i}");assert_eq!(snapshot(&q,&voice),row["after"],"reused slot and other live/padding bytes {i}");assert_eq!(json!(backend.inner.calls),row["calls"],"all physical calls {i}");assert_eq!(json!(backend.inner.freed),row["freed"],"retired addresses {i}");}}

 struct ControlBackend{inner:Backend,control:Runtime}
 impl crate::audio_path_voice_control_publication::Services for ControlBackend{
 fn allocate_control(&mut self,_:u32,_:u32)->Result<Option<Memory>,Error>{Err(Error::Backend("preallocated native control cases never allocate"))}
 fn drain_controls(&mut self,_:&mut Runtime)->Result<(),Error>{Err(Error::Backend("preallocated native control cases never drain"))}
 }
 impl Services for ControlBackend{
 fn allocate_notification(&mut self,p:u32,n:u32)->Result<Option<Memory>,Error>{self.inner.allocate_notification(p,n)}
 fn free_notification(&mut self,p:u32,n:&Memory)->Result<(),Error>{self.inner.free_notification(p,n)}
 fn voice_action(&mut self,v:&mut Memory,a:u32,q:&mut Runtime)->Result<(),Error>{
 self.inner.voice_action(v,a,q)?;
 let mut control=std::mem::replace(&mut self.control,Runtime{header:[0;28],regions:BTreeMap::new(),freed_nodes:BTreeSet::new(),pool:0});
 let result=crate::audio_path_voice_control_publication::immediate_action(&mut control,v,a,self);self.control=control;result
 }
 }
 #[test]fn audio_path_voice_notification_matches3072_native_actual_immediate_action_control_publication_and_both_queue_bytes(){
 let p:Value=serde_json::from_str(&crate::audio_test_fixture("data/4.20/audio_path_voice_notification_control_publication_preparation.json")).unwrap();assert_eq!(p["passed"],true);assert_eq!(p["case_count"],3072);
 for(i,row)in p["cases"].as_array().unwrap().iter().enumerate(){let b=&row["before"];let mut voice=Memory{reference:0x40004000,raw:bytes(b["voice"].as_str().unwrap())};let mut q=Runtime{header:bytes(b["queue"].as_str().unwrap()).try_into().unwrap(),regions:BTreeMap::from([(0x40008000,Memory{reference:0x40008000,raw:bytes(b["storage"].as_str().unwrap())}),(0x40009000,Memory{reference:0x40009000,raw:bytes(b["free_slot"].as_str().unwrap())})]),freed_nodes:BTreeSet::new(),pool:17};let mut backend=ControlBackend{inner:Backend{pattern:row["pattern"].as_u64().unwrap()as u8,failure:row["failure"]==true,calls:vec![],freed:vec![]},control:Runtime{header:bytes(b["control_queue"].as_str().unwrap()).try_into().unwrap(),regions:BTreeMap::from([(0x4000b000,Memory{reference:0x4000b000,raw:bytes(b["control_node"].as_str().unwrap())})]),freed_nodes:BTreeSet::new(),pool:0}};
 assert_eq!(q.notify(&mut voice,0x12345678,&mut backend).unwrap(),row["result"].as_u64().unwrap()as u32,"status {i}");assert_eq!(json!(backend.inner.calls),row["calls"],"physical calls before actual action {i}");assert_eq!(json!(backend.inner.freed),row["freed"],"free order {i}");let allocated=q.regions.get(&0x4000a000).map(|m|hex(&m.raw)).unwrap_or_else(||b["allocated"].as_str().unwrap().to_string());assert_eq!(json!({"voice":hex(&voice.raw),"queue":hex(&q.header),"storage":hex(&q.regions[&0x40008000].raw),"free_slot":hex(&q.regions[&0x40009000].raw),"allocated":allocated,"control_queue":hex(&backend.control.header),"control_node":hex(&backend.control.regions[&0x4000b000].raw)}),row["after"],"both queues and full voice/padding bytes {i}");
 }
 }

}
